751	static int check_urb_status(struct urb *urb)
752	{
753		struct device *dev = &urb->dev->dev;
754		int status = urb->status;
755	
756		switch (status) {
757		case 0:
758			return 0;
759	
760		case -EOVERFLOW:
761			dev_err(dev, "%s: overflow actual length is %d\n",
762				__func__, urb->actual_length);
